def works(vec, mask):
	if vec[-1] & mask != vec[-1]:
		return False
	mx = 0
	for (i, v) in zip(range(len(vec)), vec):
		if i > mx:
			break
		if v & mask == v and v + i > mx:
			mx = v + i
	return mx >= len(vec) - 1
t = int(input())
for _ in range(t):
	__ = input()
	vec = [int(x) for x in input().split()]
	if not works(vec, (1 << 20) - 1):
		print(-1)
	else:
		ans = 0
		for bit in range(19, -1, -1):
			if not works(vec, ans | (1 << bit) - 1):
				ans |= 1 << bit
		print(ans)
